class Solution {
public:
    int furthestBuilding(vector<int>& heights, int bricks, int ladders) {
        int n = heights.size();
        priority_queue<int, vector<int>, greater<int>> pq;
        long long brickCost = 0;

        for (int i = 0; i < n - 1; i++) {
            int diff = heights[i + 1] - heights[i];
            if (diff <= 0) continue;

            pq.push(diff);
            if ((int)pq.size() > ladders) {
                brickCost += pq.top();
                pq.pop();
            }
            if (brickCost > bricks) {
                return i;
            }
        }

        return n - 1;
    }
};
